group by hdr.NUM_TRX, hdr.FECHA_TRX, hdr.NUM_TIENDA, hdr.TIPO_TRX, hdr.MNT_TOTAL_A_PAGAR,
         hdr.MNT_TOT_SN_IMPTOS, hdr.MNT_REDONDEO, p.ID, p.TRANSACTIONTYPE, p.POINTS
ORDER BY 1;



SELECT NUM_TRX, FECHA_TRX, NUM_TIENDA, NUM_CAJA, NUM_TICKET, TIPO_TRX,
       MNT_TOTAL_A_PAGAR, MNT_TOT_SN_IMPTOS, TRX_ORIGINAL
FROM TRX_HDR
WHERE NUM_TRX = '2026071610500066579';